from pathlib import Path
ROOT=Path(__file__).resolve().parents[4];SRC=ROOT/'research/20261114/loki/h3ad';PUBLIC=ROOT/'results/research/loki/h3ad'
def main():
    s=json.loads((PUBLIC/'summary.json').read_text());assert s['status']=='validated';lines=[]
    def add(v=''):lines.append(v)
    add('# H3ad: the fixed search recipe on two new rule families');add();add(f"**The frozen two-family conjunction is {s['decision']}.** The study extends the positive-F BP AdamW search comparison to two fixed new families: ordinary queens plus a zebra leaper (2,3), and ordinary queens plus a (2,5) leaper. Each uses its complete N12 source bank, the unchanged 4,000-update fit, and source-calibrated arbitrary versus permutation proposals on a fresh N13 cohort. No families are replaced or chosen using target search results.")
    add();add('![Two new rule families](../../../../results/research/loki/h3ad/new-family-replication.png)');add();add('| Family | Complete N12 source boards | Complete N13 target boards | Source/target completeness | Decision |');add('|---|---:|---:|---|---|')
