    add();add('| Family | Method | Cap | Certified primary (%) | Certificate-first fallback (%) | Valid coverage (%) | Median solve seconds | Wrong stops |');add('|---|---|---:|---:|---:|---:|---:|---:|')
    for r in s['rows']:add(f"| {r['family']} | {r['arm']} | {r['cap']:,} | {r['certified_success_pct']:.6f} | {r['certificate_first_accuracy_pct']:.6f} | {r['coverage_pct']:.6f} | {r['median_worker_solve_seconds']:.6f} | {r['wrong_stops']} |")
    add();add('| Family | Gain (pp) | 97.5% one-sided lower / upper endpoints (pp) | Quality decision | Fresh time ratio |');add('|---|---:|---:|---|---:|')
